const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const x = data.slice(1, 1 + n);
const h = Math.max(...x);

const lines = [];
for (let level = h; level >= 1; level--) {
  const row = [];
  for (let i = 0; i < n; i++) {
    row.push(level <= x[i] ? 1 : 0);
  }
  lines.push(row.join(' '));
}

console.log(lines.join('\n'));
